import{_ as h}from"./chunks/TST-Setup.B0ESPk6n.js";import{_ as p}from"./chunks/BOF-Setup.CrO0nm7W.js";import{_ as c}from"./chunks/BPB-Setup.B_dGNHDA.js";import{_ as u}from"./chunks/PB-Setup.Cez2TMFY.js";import{_ as d}from"./chunks/CPB-Setup.Dj-JIWYv.js";import{_ as g,C as r,c as m,o as f,aj as a,G as i,w as n,j as e}from"./chunks/framework.Bfdr4H5E.js";const w="/sk/images/Initial-Market-Analysis-Process.webp",y="/sk/images/Ongoing-Market-Analysis-Benefits.webp",k="/sk/images/Ongoing-Market-Analysis-Process.webp",b="/sk/images/Trading-Process.webp",v="/sk/images/Setups-Poster.webp",P="/sk/images/Development-Stages.webp",R=JSON.parse('{"title":"Summary - Trading with PAV","description":"","frontmatter":{"outline":"deep","prev":{"text":"What Instruments (Scripts) to Trade","link":"/trading-with-pav/what-instruments-scripts-to-trade"},"next":{"text":"10 Most Common Trading Mistakes You Should Avoid","link":"/trading-with-pav/10-most-common-trading-mistakes-you-should-avoid"}},"headers":[],"relativePath":"trading-with-pav/summary-trading-with-pav.md","filePath":"trading-with-pav/summary-trading-with-pav.md"}'),S={name:"trading-with-pav/summary-trading-with-pav.md"};function T(x,t,A,I,q,_){const s=r("ProtectedPage"),o=r("GraphComment"),l=r("ClientOnly");return f(),m("div",null,[t[2]||(t[2]=a('<h1 id="summary-trading-with-pav" tabindex="-1">Summary - Trading with PAV <a class="header-anchor" href="#summary-trading-with-pav" aria-label="Permalink to &quot;Summary - Trading with PAV&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#summary-–-trading-with-pav">Summary – Trading with PAV</a></li><li><a href="#principles-of-markets">Principles of Markets</a></li><li><a href="#market-analysis">Market Analysis</a><ul><li><a href="#initial-market-analysis-process">Initial Market Analysis Process:</a></li><li><a href="#initial-market-analysis-checklist">Initial Market Analysis Checklist</a></li><li><a href="#ongoing-market-analysis-–-theory">Ongoing Market Analysis – Theory</a></li><li><a href="#ongoing-market-analysis-process">Ongoing Market Analysis Process</a></li><li><a href="#ongoing-market-analysis-checklist">Ongoing Market Analysis Checklist</a></li><li><a href="#principles-of-future-trend-direction">Principles of Future Trend Direction</a></li></ul></li><li><a href="#trading-strategy">Trading Strategy</a></li><li><a href="#setups-appropriate-for-each-particular-market-environment">Setups Appropriate for each Particular Market Environment:</a></li><li><a href="#trading-process">Trading Process</a><ul><li><a href="#trading-process-diagram">Trading Process Diagram</a></li><li><a href="#trading-process-checklist">Trading Process Checklist</a></li><li><a href="#step-3-–-trade-management-exit">Step 3 – Trade Management &amp; Exit</a></li></ul></li><li><a href="#setups-poster">Setups Poster</a></li><li><a href="#the-learning-process">The Learning Process</a></li><li><a href="#development-stages">Development Stages</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="summary-–-trading-with-pav" tabindex="-1">Summary – Trading with PAV <a class="header-anchor" href="#summary-–-trading-with-pav" aria-label="Permalink to &quot;Summary – Trading with PAV&quot;">​</a></h2><p>Let&#39;s summarize the key points that we learn in this course from YSTC’s “<strong>Trading with Price Action Volume</strong>”. Lets start the Trading with PAV – Summary with Principles.</p><h2 id="principles-of-markets" tabindex="-1">Principles of Markets <a class="header-anchor" href="#principles-of-markets" aria-label="Permalink to &quot;Principles of Markets&quot;">​</a></h2><p>Markets are traders making trading decisions.</p><p>Price movement is a result of supply/demand imbalance. And the supply/demand imbalance is created by the traders’ sense of urgency to transact.</p><div class="warning custom-block"><p class="custom-block-title">Price moves due to following 4 points of supply/demand imbalance</p><ul><li>Price rises while demand is greater than supply, and while those buyers are willing to pay higher prices.</li><li>Price rises until we run out of buyers, or until supply increases sufficiently to absorb all the demand.</li><li>Price falls while supply is greater than demand, and while those sellers are willing to sell at lower prices.</li><li>Price falls until we run out of sellers, or until demand increases to the point it absorbs all the supply.</li></ul></div><p>Price moves with changes in the forces of supply and demand. Supply and demand change as the sentiment of the crowd changes. And the sentiment of the crowd changes with changes in the bullish or bearish sentiment of the market participants.</p><p>Trading is not about the Fundamentals or Technicals. It’s about people… and the decisions they make about market direction.</p><p>Price moves as a collective result of all traders’ bullish or bearish sentiment and their <strong>decisions to act</strong> in the market (buy or sell).</p><p>Learn to view all price movement from the perspective of other traders, and how the price movement influences their decision making.</p><p>The aim of your analysis then MUST be the following:</p><div class="warning custom-block"><p class="custom-block-title">Aim of your analysis</p><ul><li>To buy at areas where you KNOW others will buy after you, because their buying will create the net order-flow or bullish pressure to drive prices higher, allowing you opportunity to profit, or</li><li>To sell at areas where you KNOW others will sell after you, because their selling will create the net order-flow or bearish pressure to drive prices lower, allowing you opportunity to profit.</li></ul></div><p>Or more simply; buy at areas where others will buy after you, and sell at areas where others will sell after you.</p><div class="tip custom-block"><p class="custom-block-title">Buy\\Sell Areas analysis</p><ul><li>To do that, your analysis must focus on areas of trader decisions.</li><li>What are other traders thinking? Where will they be making their trading decisions?</li><li>Identify areas at which others will be making buying decisions, and you can profit.</li><li>Identify areas at which others will be making selling decisions, and you can profit.</li></ul></div><p>Individual trader decisions are unknown. However we can, through our analysis, identify areas where significant groups of traders will be under extreme stress, and therefore feel forced to act in a reasonably predictable manner.</p><p>We aim to enter before or at the point of maximum stress, where traders are coming to accept they’re wrong.</p><p>Their decision to exit is a means of relieving themselves of stress. This creates order-flow that takes our position to profit (provided of course you manage the trade well).</p><h2 id="market-analysis" tabindex="-1">Market Analysis <a class="header-anchor" href="#market-analysis" aria-label="Permalink to &quot;Market Analysis&quot;">​</a></h2><h3 id="initial-market-analysis-process" tabindex="-1">Initial Market Analysis Process: <a class="header-anchor" href="#initial-market-analysis-process" aria-label="Permalink to &quot;Initial Market Analysis Process:&quot;">​</a></h3><p><img src="'+w+'" alt="Initial-Market-Analysis-Process"></p><p>Initial Market Analysis Process</p><p>Initial Market Analysis involves a six step process, as per figure above. The following checklist will walk you through the actions required for each step.</p><h3 id="initial-market-analysis-checklist" tabindex="-1">Initial Market Analysis Checklist <a class="header-anchor" href="#initial-market-analysis-checklist" aria-label="Permalink to &quot;Initial Market Analysis Checklist&quot;">​</a></h3><h4 id="step-1-–-define-structure" tabindex="-1">Step 1 – Define Structure <a class="header-anchor" href="#step-1-–-define-structure" aria-label="Permalink to &quot;Step 1 – Define Structure&quot;">​</a></h4><p>Define a <a href="/sk/trading-with-pav/htf-market-structure/">structural framework</a> within which our trading timeframe price action will move.</p><ul><li><strong>Actions</strong>: <ul><li>Identify areas of <a href="/sk/trading-with-pav/support-and-resistance/">Support or Resistance</a> on the higher timeframe (30 min) chart <ul><li>Swing highs and lows</li></ul></li></ul></li></ul><h4 id="step-2-define-trend" tabindex="-1">Step 2 -Define Trend <a class="header-anchor" href="#step-2-define-trend" aria-label="Permalink to &quot;Step 2 -Define Trend&quot;">​</a></h4><p>Assess the movement of past price action within our market structure framework.</p><ul><li><strong>Actions</strong>: <ul><li>Identify significant swing highs and lows on the trading timeframe (3 min) chart.</li><li>Identify the <a href="/sk/trading-with-pav/ttf-trends/">trend</a> direction <ul><li><a href="/sk/trading-with-pav/uptrend/">Up</a>, <a href="/sk/trading-with-pav/downtrend/">down</a> or <a href="/sk/trading-with-pav/sideways-trend/">sideways</a>.</li></ul></li></ul></li></ul><h4 id="step-3-–-identify-strength-weakness" tabindex="-1">Step 3 – Identify Strength &amp; Weakness <a class="header-anchor" href="#step-3-–-identify-strength-weakness" aria-label="Permalink to &quot;Step 3 – Identify Strength &amp; Weakness&quot;">​</a></h4><p>Analyze price movement within the trend to identify signs of strength or weakness.</p><ul><li><strong>Actions</strong>: <ul><li>Analyze momentum of recent price swings <ul><li>Compare the momentum of the current price swing with the momentum of the previous price swing in the <a href="/sk/trading-with-pav/momentum-speed-acceleration/#momentum-comparison--same-direction-swings">same direction</a>? Is price faster or slower than before?<br> What does that mean?</li><li>Compare the momentum of the current price swing with the momentum of the previous price swing in the <a href="/sk/trading-with-pav/momentum-speed-acceleration/#momentum-comparisons--opposite-direction-swings">opposite direction</a>? Is price faster or slower than before? What does that mean?</li><li>Is the current price <a href="/sk/trading-with-pav/momentum-speed-acceleration/#momentum-comparisons--acceleration">accelerating</a> or <a href="/sk/trading-with-pav/momentum-speed-acceleration/#momentum-comparisons--deceleration">decelerating</a>? What does that mean?</li></ul></li><li>Compare projection and depth of recent price swings (not taught instead use <a href="/sk/trading-with-pav/fibonacci-retracement/">Fibonacci</a>) <ul><li>Increased projection is a sign of potential trend strength. Decreased projection is a sign of potential trend weakness.</li><li>Increased depth is a sign of potential trend weakness. Decreased depth is a sign of potential trend strength.</li></ul></li><li>Identify signs of failure to continue (i.e.. failure to meet expectations). <ul><li><a href="/sk/trading-with-pav/entry/#stall">Failure to continue</a> is a sign of weakness</li></ul></li><li>Identify signs of strength or weakness via any miscellaneous methods <ul><li><a href="/sk/trading-with-pav/volume-price-analysis/">Volume Price Analysis</a> (all <a href="/sk/trading-with-pav/vpa-building-the-picture/">VPA Building the picture</a> method)</li><li>Market Internal indicators (e.g. RSI)</li></ul></li></ul></li></ul><h4 id="step-4-–-identify-future-trend-direction" tabindex="-1">Step 4 – Identify Future Trend Direction <a class="header-anchor" href="#step-4-–-identify-future-trend-direction" aria-label="Permalink to &quot;Step 4 – Identify Future Trend Direction&quot;">​</a></h4><p>What is the likely path of future price action?</p><ul><li><strong>Actions</strong>: <ul><li>Determine the likely path of future price action, in accordance with the following six principles: <ul><li>Mentioned <a href="/sk/trading-with-pav/summary-trading-with-pav/#principles-of-future-trend-direction">HERE</a>.</li></ul></li></ul></li></ul><h4 id="step-5-–-visualize-future-price-action" tabindex="-1">Step 5 – Visualize Future Price Action <a class="header-anchor" href="#step-5-–-visualize-future-price-action" aria-label="Permalink to &quot;Step 5 – Visualize Future Price Action&quot;">​</a></h4><p>How do you expect price to behave? <a href="/sk/trading-with-pav/principles-of-future-trend-direction/#visualizing-the-future">Visualize the future</a> price action, based upon your expectations for future trend direction and its interaction with the market structure S/R levels.</p><ul><li><strong>Actions</strong>: <ul><li>What price action would validate your assessment of future trend direction?</li><li>What price action would invalidate your assessment of future trend direction?</li></ul></li></ul><h4 id="step-6-–-identify-areas-of-trade-opportunity" tabindex="-1">Step 6 – Identify Areas of Trade Opportunity <a class="header-anchor" href="#step-6-–-identify-areas-of-trade-opportunity" aria-label="Permalink to &quot;Step 6 – Identify Areas of Trade Opportunity&quot;">​</a></h4><ul><li>5 Basic Price Action Setups at as price interacts with levels of S/R. 1. <a href="/sk/trading-with-pav/tst-setup/">TST Setup</a> 2. <a href="/sk/trading-with-pav/bof-setup/">BOF Setup</a> 3. <a href="/sk/trading-with-pav/bpb-setup/">BPB Setup</a><ul><li>2 occur within a trend. 4. <a href="/sk/trading-with-pav/pb-setup/">PB Setup</a> 5. <a href="/sk/trading-with-pav/cpb-setup/">CPB Setup</a></li></ul></li><li>Price Action Strategies <ol><li>Strategy 1: <a href="/sk/trading-with-pav/price-action-strategies/#strategy-1-support-becoming-resistance--vice-versa">Support becoming resistance (&amp; vice versa)</a></li><li>Strategy 2: <a href="/sk/trading-with-pav/price-action-strategies/#strategy-2-opendrive">Open-drive</a></li><li>Strategy 3: <a href="/sk/trading-with-pav/price-action-strategies/#strategy-3-ab--cd">AB = CD</a></li><li>Strategy 4: <a href="/sk/trading-with-pav/price-action-strategies/#strategy-4-dailyweekly-high-and-low">Daily/weekly high and low</a></li><li><a href="/sk/trading-with-pav/price-action-strategies/#strong-or-weak-highslows">Strong or weak highs/lows</a><ul><li><a href="/sk/trading-with-pav/price-action-strategies/#strong-highlow">Strong high/low</a></li><li><a href="/sk/trading-with-pav/price-action-strategies/#weak-highlow">Weak high/low</a></li></ul></li></ol></li><li>Volume Profile – Trading Setups <ul><li>VP Setup #1: <a href="/sk/trading-with-pav/volume-accumulation-setup/">Volume Accumulation Setup</a></li><li>VP Setup #2: <a href="/sk/trading-with-pav/trend-setup/">Trend Setup</a></li><li>VP Setup #3: <a href="/sk/trading-with-pav/rejection-setup/">Rejection Setup</a></li><li>VP Setup #4: <a href="/sk/trading-with-pav/reversal-trades/">Reversal trades</a></li></ul></li></ul><p><strong>Next Process Step?</strong><br> That concludes our initial analysis.</p><p>From here we conduct our ongoing analysis process – an ongoing process of updating our assessment of likely future trend and areas of trade opportunity, based upon new information provided by each and every candle.</p><p>That’s the subject of sections 3.5 (Ongoing Market Analysis – Theory) and 3.6 (Ongoing Market<br> Analysis Process).</p><p><strong>KEEP IT SIMPLE</strong></p><p>The initial analysis process has taken many articles to describe, as I’ve attempted to do so<br> in as simple as possible. As you’ll later experience yourself later when practicing, the process itself is quite simple and should take no more than a minute or so on initial opening of your charts.</p><p>Be careful not to get caught up in complexity. The process should be SIMPLE. If it’s not, then you’re probably trying too hard to predict exactly where price is going. This is not about prediction. We’re simply assessing the likely future path. We’ll then be monitoring ongoing price action to confirm that path, or amend it.</p><p><strong>Don’t be afraid to get it wrong. Ongoing analysis will be self-correcting.</strong></p><p>If you’re finding it too hard, just refer back to our simple checklist steps above.<br> That’s all there is to it.</p><p>We now move on to ongoing analysis.</p><p>Remember – the analysis we have conducted so far is just my initial assessment of likely future trend direction. I’ll be updating that assessment bar by bar as new data unfolds. So, if I’m wrong I’ll see it in a very timely manner, allowing me to reassess and adjust my expectations. And if I’m right, I’ll be prepared for any trade opportunity that will present, as price follows my expected path.</p><h3 id="ongoing-market-analysis-–-theory" tabindex="-1">Ongoing Market Analysis – Theory <a class="header-anchor" href="#ongoing-market-analysis-–-theory" aria-label="Permalink to &quot;Ongoing Market Analysis – Theory&quot;">​</a></h3><p>Our initial analysis resulted in an initial assessment of the future trend direction. Ongoing analysis requires a bar by bar reassessment of our previous analysis, as more price action unfolds on the right hand side of our chart.</p><p>New data will arrive, one candle at a time. Each new candle being a source of information; most of which will offer nothing new or relevant; but some of which will alter our analysis, either strengthening or weakening our assessment of market sentiment and future price direction.</p><p><strong>Every new candle is potentially significant.</strong></p><p>Failing to monitor price with each new candle means we will be forced to be reactionary – surprised by price action developments and chasing setups and entries after they’ve become obvious to the crowd.</p><p>Ongoing monitoring ensures we maintain focus and maintain situational awareness – staying ahead of the current price action – assessing where it’s likely to travel, how that will impact the decision making of other traders, and where that will create trade opportunity.</p><p><img src="'+y+'" alt="Ongoing-Market-Analysis-Benefits"></p><p>The Benefits of Ongoing Price Action Analysis</p><p>Ongoing price action analysis can be conducted on all timeframes, however our main interest is with the trading timeframe. We question EVERY candle, to determine what it means with regards to the shift in sentiment between the bulls and the bears; and whether or not it changes our expectations for the future.</p><p>This is a step by step process, the first part of which is assessing the sentiment of the current candle with volume.</p><p>Use Volume and rejection candles articles <a href="/sk/trading-with-pav/volume/">39</a>, <a href="/sk/trading-with-pav/volume-price-analysis/">40</a>, <a href="/sk/trading-with-pav/rejection-candles/">42</a>, <a href="/sk/trading-with-pav/vpa-building-the-picture/">43</a> for bar by bar volume analysis. Analysis tips as below</p><p>Where is price in relation to S/R? Where is it in the trend? Where is it in relation to key swing highs and lows? And what does this mean?</p><p><strong>Support and Resistance</strong>:</p><ul><li>Where is the PAV occurring with respect to higher timeframe support and resistance?</li><li>Has the market shown strength or weakness on approach to the S/R area? Is the current VPA sentiment continuing this strength or weakness, or has something changed?</li><li>Is the Rejection candles showing signs of order-flow opposing the move into S/R, such as tails rejecting price at or near the S/R level?</li><li>Has the VPA breached the area of S/R? If so, is it now showing signs of acceptance or rejection of this new area?</li></ul><p><strong>Trend:</strong></p><ul><li>Where is the Rejection candles occurring within the current trend?</li><li>Is it on an extension? Is it early in the move, or late and overextended? Has it projected past the previous swing high/low?</li><li>Is it on a pullback? Is it early in the move, or has it continued deeper than anticipated? Is it a single swing pullback, or is this pattern a part of a multiple swing retracement.</li><li>Or is the pattern within a sideways trading range or other form of consolidation pattern?</li></ul><p><strong>Swing Highs and Lows:</strong></p><ul><li>Is price testing any areas of swing highs or lows? Of particular importance are those which lead to a change of trend definition; how is price reacting at those swing highs or lows?</li></ul><p><strong>For an uptrend:</strong></p><ul><li>Pullbacks to previous areas of swing low support should be watched closely. We expect them to hold. Is the price action showing signs of the level holding, or is it threatening to break? If it breaks, is price showing signs of rejection (opposing order-flow / difficulty continuing) or is price accepting this new area?</li><li>Pullbacks to previous swing highs (within an uptrend) are not as critical, but should still be watched for their reaction.</li><li>Extensions are expected to break the previous swing high. Is price action supporting that premise, or is the VPA showing weakness. If it can’t exceed the previous swing high, we need to be alert for further signs of weakness which may forecast a complex correction or reversal.</li></ul><p><strong>For a downtrend:</strong></p><ul><li>Pullbacks to previous areas of swing high resistance should be watched closely. We expect them to hold. Is the price action showing signs of the level holding, or is it threatening to break? If it breaks, is price showing signs of rejection (opposing order-flow / difficulty continuing) or is price accepting this new area?</li><li>Pullbacks to previous swing lows (within a downtrend) are not as critical, but should still be watched for their reaction.</li><li>Extensions are expected to break the previous swing low. Is price action supporting that premise, or is the VPA showing weakness. If it can’t break the previous swing low, we need to be alert for further signs of weakness which may forecast a complex correction or reversal.</li></ul><p><strong>For a sideways trend:</strong></p><ul><li>Is price testing a range boundary?</li><li>Has the market shown strength or weakness on approach to the boundary? Is the current VA sentiment continuing this strength or weakness, or has something changed?</li><li>Is the pattern showing signs of order-flow opposing the move into the range boundary, such as tails rejecting price at or near the level?</li><li>Has the pattern breached the area of range S/R? If so, is it now showing signs of acceptance or rejection of this new area?</li></ul><h3 id="ongoing-market-analysis-process" tabindex="-1">Ongoing Market Analysis Process <a class="header-anchor" href="#ongoing-market-analysis-process" aria-label="Permalink to &quot;Ongoing Market Analysis Process&quot;">​</a></h3><p>Ongoing Market Analysis Process:</p><p><img src="'+k+'" alt="Ongoing-Market-Analysis-Process"></p><p>Ongoing Market Analysis Process</p><p>Ongoing (Bar by Bar) Market Analysis involves a four step process, as shown in figure above.</p><p>The following checklist will walk you through the actions required for each step.</p><h3 id="ongoing-market-analysis-checklist" tabindex="-1">Ongoing Market Analysis Checklist <a class="header-anchor" href="#ongoing-market-analysis-checklist" aria-label="Permalink to &quot;Ongoing Market Analysis Checklist&quot;">​</a></h3><h4 id="step-1-–-determine-pattern-sentiment" tabindex="-1">Step 1 – Determine Pattern Sentiment <a class="header-anchor" href="#step-1-–-determine-pattern-sentiment" aria-label="Permalink to &quot;Step 1 – Determine Pattern Sentiment&quot;">​</a></h4><p>Classify the candle pattern and determine the short-term sentiment of price.</p><ul><li><strong>Actions</strong>: <ul><li>Classify the Rejection candle with volume. <ul><li>Candles which are <strong>Long Upper Wick</strong>/Shadow are <ol><li>Shooting Star (Bearish)</li><li>Inverted Hammer (Bullish)</li><li>Gravestone Doji (Bearish)</li></ol></li><li>Candles which are <strong><strong>Doji</strong></strong> (Indecision) are 4. Doji (Indecision)</li><li>Candles which are <strong>Long Lower Wick</strong>/Shadow are 5. Hammer (Bullish) 6. Hanging Man (Bearish) 7. Dragonfly Doji (Bullish)</li></ul></li><li>Determine the sentiment of the pattern.</li></ul></li></ul><h4 id="step-2-–-consider-the-context" tabindex="-1">Step 2 – Consider the Context <a class="header-anchor" href="#step-2-–-consider-the-context" aria-label="Permalink to &quot;Step 2 – Consider the Context&quot;">​</a></h4><p>Every pattern is unique and MUST be considered in the context of the background market environment in which it occurs.</p><ul><li><strong>Actions</strong>: <ul><li>Where is the current price action in relation to key market structure features: <ul><li>Support or Resistance</li><li>Trend</li><li>Swing Highs and Lows</li></ul></li><li>What does this mean with respect to the sentiment of the pattern and the potential future price action?</li></ul></li></ul><h4 id="step-3-–-does-it-support-my-premise" tabindex="-1">Step 3 – Does it Support my Premise? <a class="header-anchor" href="#step-3-–-does-it-support-my-premise" aria-label="Permalink to &quot;Step 3 – Does it Support my Premise?&quot;">​</a></h4><p>Is the market action continuing as expected, or is something indicating we’re out of sync with market flow?</p><ul><li><strong>Actions</strong>: <ul><li>Does the current price action and sentiment support our previous expectations for future price action? <ul><li>Yes <ul><li>Await further price information.</li></ul></li><li>No <ul><li>Decide whether to hold for the next candle, or to reconsider the Initial Market Analysis.</li></ul></li><li>Unsure <ul><li>Wait for further price information.</li></ul></li></ul></li></ul></li></ul><h4 id="step-4-–-repeat" tabindex="-1">Step 4 – Repeat <a class="header-anchor" href="#step-4-–-repeat" aria-label="Permalink to &quot;Step 4 – Repeat&quot;">​</a></h4><ul><li><strong>Actions</strong>: <ul><li>Repeat the process as new information appears on the chart.</li></ul></li></ul><p><strong>KEEP IT SIMPLE</strong></p><p>As with the initial analysis process, this ongoing analysis has taken many articles to describe. However, what may appear to be quite a complex process is in actual fact quite simple to perform.</p><p>My analysis has developed over the years as a subjective and intuitive process.</p><p>The complexity appears as a result of trying to get the essence of that process into writing and teaching, in as reproducible form as possible.</p><p>Once again, the ongoing analysis should take no more than maybe 10-15 seconds. Any more than that and you’re trying too hard to find certainty, where there is none.</p><p>Experience will rapidly improve your ability to read the market flow. And in time you’ll do so without checklists. In the meantime, use them as a prompt.</p><ul><li>You already have an expectation for where price is going.</li><li>Is the latest price action supporting that premise, or does it need to be reconsidered?</li></ul><p>That’s the two sentence summary version of “Ongoing Bar-by-Bar Market Analysis”.<br><strong>Keep it simple. And as before, don’t be afraid to get it wrong. Ongoing analysis will be self-correcting.</strong></p><h3 id="principles-of-future-trend-direction" tabindex="-1">Principles of Future Trend Direction <a class="header-anchor" href="#principles-of-future-trend-direction" aria-label="Permalink to &quot;Principles of Future Trend Direction&quot;">​</a></h3><h4 id="within-the-s-r-framework" tabindex="-1">Within the S/R framework: <a class="header-anchor" href="#within-the-s-r-framework" aria-label="Permalink to &quot;Within the S/R framework:&quot;">​</a></h4><ul><li><strong>First Principle</strong> – We expect an up or down trend to continue in its current state until the next S/R barrier, unless displaying evidence of weakness within the trend.</li><li><strong>Second Principle</strong> – When an up or down trend shows evidence of weakness, we expect a higher likelihood of a complex correction* rather than a reversal, until such time as the market shows both price acceptance and strength in the new trend direction.<br> (* a complex correction being one of extended duration, or multiple swings)</li><li><strong>Third Principle</strong> – A sideways trend within the framework is expected to continue in its current state, unless displaying evidence of strength towards the range boundary.</li><li><strong>Fourth Principle</strong> – When a sideways trend shows evidence of strength towards the range boundary, we expect a break of the boundary. We observe the behavior of price post-breakout for clues as to future direction: <ul><li>Weakness following the breakout – the expectation is for a breakout failure and reversal back within the trading range</li><li>Weakness on the pullback – the expectation is for a breakout pullback and continuation.</li></ul></li></ul><h4 id="at-the-edges-of-the-s-r-framework" tabindex="-1">At the edges of the S/R framework: <a class="header-anchor" href="#at-the-edges-of-the-s-r-framework" aria-label="Permalink to &quot;At the edges of the S/R framework:&quot;">​</a></h4><ul><li><strong>Fifth Principle</strong> – We expect a test of our framework S/R to hold, unless strength is displayed on approach to the S/R boundary.</li><li><strong>Sixth Principle</strong> – If strength is shown on an approach to an S/R barrier, we expect a breakout and watch the behavior of price post-breakout for clues as to future direction: <ul><li>Weakness following the breakout – the expectation is for a breakout failure and reversal back through the area of S/R.</li><li>Weakness on the pullback – the expectation is for a breakout pullback and continuation</li></ul></li></ul><h2 id="trading-strategy" tabindex="-1">Trading Strategy <a class="header-anchor" href="#trading-strategy" aria-label="Permalink to &quot;Trading Strategy&quot;">​</a></h2>',108)),i(s,null,{default:n(()=>t[0]||(t[0]=[e("p",null,"Find the areas on a chart where other traders will make trading decisions and you’ve got yourself an edge.",-1),e("p",null,"Enter at or before the change of net order flow and you’ve got a great opportunity to profit (provided you manage the trade well).",-1),e("p",null,"Our trading approach therefore needs to be based on this fundamental understanding of how to profit from the markets:",-1),e("ul",null,[e("li",null,"We identify areas at which sufficient numbers of traders will be experiencing stress, and will make trading decisions to relieve them of that stress, and then act before or with them in order to profit from the resultant order-flow.")],-1),e("p",null,"We aim to find places on the chart where other traders are fighting the bias. We identify the areas where they realize they’re wrong and are forced to exit.",-1),e("p",null,"There are two primary concepts behind all my setups – fading weakness and fading trapped traders.",-1),e("p",null,"Identify weakness. Identify trapped traders. Fade the weakness and be part of the order-flow which springs the trap.",-1),e("p",null,[e("img",{src:h,alt:"TST-Setup"})],-1),e("p",null,"Test Setup (TST)",-1),e("p",null,[e("img",{src:p,alt:"BOF-Setup"})],-1),e("p",null,"Breakout Failure Setup (BOF)",-1),e("p",null,[e("img",{src:c,alt:"BPB-Setup"})],-1),e("p",null,"Breakout Pullback Setup (BPB)",-1),e("p",null,[e("img",{src:u,alt:"PB-Setup"})],-1),e("p",null,"PB Setup",-1),e("p",null,[e("img",{src:d,alt:"CPB-Setup"})],-1),e("p",null,"CPB Setup",-1)])),_:1,__:[0]}),t[3]||(t[3]=a('<h2 id="setups-appropriate-for-each-particular-market-environment" tabindex="-1">Setups Appropriate for each Particular Market Environment: <a class="header-anchor" href="#setups-appropriate-for-each-particular-market-environment" aria-label="Permalink to &quot;Setups Appropriate for each Particular Market Environment:&quot;">​</a></h2><ul><li>Steady trend environment: <ul><li>Higher Probability <ul><li>PB and CPB</li></ul></li></ul></li><li>Weakening trend environment <ul><li>Higher Probability <ul><li>CPB</li><li>PB if they break a previous swing low (uptrend) or swing high (downtrend)</li></ul></li><li>Lower Probability <ul><li>Standard PB (single leg; not breaking any prior swing low (uptrend) or swing high (downtrend))</li><li>Counter-trend TST or BOF of swing high (uptrend) or swing low (downtrend)</li></ul></li></ul></li><li>Within a Sideways Trading Range with a clear intra-range trend <ul><li>Lower Probability <ul><li>PB and CPB</li></ul></li></ul></li><li>Approaching higher timeframe S/R or range S/R, with no sign of potential breakout <ul><li>Higher Probability <ul><li>TST</li></ul></li></ul></li><li>Approaching higher timeframe S/R or range S/R, with strength showing signs of potential breakout <ul><li>Higher Probability <ul><li>BOF or BPB</li></ul></li></ul></li></ul><h2 id="trading-process" tabindex="-1">Trading Process <a class="header-anchor" href="#trading-process" aria-label="Permalink to &quot;Trading Process&quot;">​</a></h2><h3 id="trading-process-diagram" tabindex="-1">Trading Process Diagram <a class="header-anchor" href="#trading-process-diagram" aria-label="Permalink to &quot;Trading Process Diagram&quot;">​</a></h3><p><img src="'+b+'" alt="Trading-Process"></p><p>Trading Process</p><p>The trading process involves four steps, as per above figure.<br> The following checklist will guide you through the actions required for each step.</p><h3 id="trading-process-checklist" tabindex="-1">Trading Process Checklist <a class="header-anchor" href="#trading-process-checklist" aria-label="Permalink to &quot;Trading Process Checklist&quot;">​</a></h3><h4 id="step-1-–-trade-preparation" tabindex="-1">Step 1 – Trade Preparation <a class="header-anchor" href="#step-1-–-trade-preparation" aria-label="Permalink to &quot;Step 1 – Trade Preparation&quot;">​</a></h4><p>Prepare for possible trade opportunity as price enters the vicinity of a setup area.</p><ul><li><strong>Actions</strong>: <ul><li>Monitor price movement confirming it matches the behavior previously anticipated. If price action differs from expectations, return to the initial analysis and recheck premise and assumptions.</li><li>Identify trade parameters <ul><li>Stop loss location</li><li>Targets T1 &amp; T2</li><li>Confirm entry zone <ul><li>Consider both LWP (if identified) and LRP</li></ul></li></ul></li><li>Identify preferred entry plan <ul><li>Stop and/or limit order</li></ul></li><li>Final confirmation <ul><li>The setup and trade is valid for this market environment</li><li>Price action is supporting the trade premise.</li></ul></li></ul></li></ul><h4 id="step-2-–-trade-entry" tabindex="-1">Step 2 – Trade Entry <a class="header-anchor" href="#step-2-–-trade-entry" aria-label="Permalink to &quot;Step 2 – Trade Entry&quot;">​</a></h4><p>Manage the entry into the trade, achieving the best possible price within the entry zone.</p><ul><li><strong>Actions</strong>: <ul><li>Monitor price movement bar by bar, until the entry locations are identified. Ensure price continues to support the trade premise. <ul><li>Determine candle pattern sentiment</li><li>Consider the context</li><li>Does it support my premise</li></ul></li><li>If working an entry, place an appropriate order in the market as soon as the entry decision is made.</li><li>Confirm pending order details are correct. <ul><li>Entry price, direction, size,</li><li>Contingent stop and target orders</li></ul></li><li>On fill: <ul><li>Cancel other no longer required pending orders.</li><li>Confirm full or partial position filled.</li></ul></li><li>Post-fill confirmation (gross error check) <ul><li>How do I feel about the entry?</li><li>Confirm the setup and trade are valid for this market environment</li><li>Confirm the price action is supporting the trade premise.</li></ul></li></ul></li></ul><h3 id="step-3-–-trade-management-exit" tabindex="-1">Step 3 – Trade Management &amp; Exit <a class="header-anchor" href="#step-3-–-trade-management-exit" aria-label="Permalink to &quot;Step 3 – Trade Management &amp; Exit&quot;">​</a></h3><p>Manage an open trade in order to minimize risk and maximize opportunity. The trade should<br> remain live while the premise remains valid.</p><ul><li><strong>Actions</strong>: <ul><li>Continue monitoring price movement bar by bar. Ensure price continues to support the trade premise. <ul><li>Determine candle pattern sentiment</li><li>Consider the context</li><li>Does it support my premise</li></ul></li><li>Part One <ul><li>While premise remains valid: <ul><li>Move the stop to breakeven when we would no longer wish to be in the trade if price retraced to the entry point.</li><li>Move the stop to new levels where we would no longer wish to be in the trade if price retraced to that point.</li></ul></li><li>When premise is threatened <ul><li>Cancel position if immediate exit is required.</li><li>Else work an exit through tightening both the stop and target orders, based upon lower timeframe price action.</li></ul></li></ul></li><li>Part Two <ul><li>While premise remains valid: <ul><li>Move the stop to breakeven when we would no longer wish to be in part two if price retraced to the entry point.</li><li>Move the stop to new levels where we would no longer wish to be in part two if price retraced to that point.</li></ul></li><li>When premise is threatened <ul><li>Cancel position if immediate exit is required.</li><li>Else work an exit through tightening both the stop and target orders, based upon lower timeframe price action.</li></ul></li><li>When market shows increased strength <ul><li>Consider extension of T2 or replacement with a trailing stop.</li></ul></li></ul></li><li>On partial exit <ul><li>Confirm order correctly filled.</li></ul></li><li>On total exit <ul><li>Confirm flat</li></ul></li></ul></li></ul><h4 id="step-4-–-post-trade" tabindex="-1">Step 4 – Post-Trade <a class="header-anchor" href="#step-4-–-post-trade" aria-label="Permalink to &quot;Step 4 – Post-Trade&quot;">​</a></h4><p>Conduct post-trade administration and recovery.</p><ul><li><strong>Actions</strong>: <ul><li>Reconfigure order entry screens or DOM.</li><li>In the event of a loss: <ul><li>Consider the need for a recovery process.</li></ul></li><li>Is price setting up for a possible re-entry or subsequent setup? <ul><li>Delay any trade log entries and prepare for the new trading process.</li></ul></li><li>When time permits: <ul><li>Update trade log.</li><li>Monitor and record significant observations: <ul><li>Market structure or price action.</li><li>My trading process.</li><li>My physical and psychological state.</li></ul></li></ul></li></ul></li></ul><h2 id="setups-poster" tabindex="-1">Setups Poster <a class="header-anchor" href="#setups-poster" aria-label="Permalink to &quot;Setups Poster&quot;">​</a></h2>',21)),i(s,null,{default:n(()=>t[1]||(t[1]=[e("p",null,[e("img",{src:v,alt:"Setups-Poster"})],-1),e("p",null,"Setups Poster",-1)])),_:1,__:[1]}),t[4]||(t[4]=a('<h2 id="the-learning-process" tabindex="-1">The Learning Process <a class="header-anchor" href="#the-learning-process" aria-label="Permalink to &quot;The Learning Process&quot;">​</a></h2><p><strong>Deliberate Practice</strong>: maximize exposure and learn through a process of trial and error.</p><p><strong>Trade-Record-Review-Improve cycle</strong>:</p><ul><li><strong>Trade</strong> – self-explanatory… trade the markets in accordance with your trading plan and procedures manual.</li><li><strong>Record</strong> – record results in your trading logs and journals.</li><li><strong>Review</strong> – review your results, considering the four key questions: <ol><li>What did you expect to happen?</li><li>What did happen?</li><li>Why was there a difference?</li><li>What can you learn from this?</li></ol></li><li><strong>Improve</strong> – implement improvements, either through setting process goals for the next trading session, or through amendment to the trading plan and/or procedures manual.</li></ul><h2 id="development-stages" tabindex="-1">Development Stages <a class="header-anchor" href="#development-stages" aria-label="Permalink to &quot;Development Stages&quot;">​</a></h2><p><img src="'+P+'" alt="Development-Stages"></p><p>Development Stages</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',8)),i(l,null,{default:n(()=>[i(o)]),_:1})])}const V=g(S,[["render",T]]);export{R as __pageData,V as default};
